import random,heapq

def fast(n, edges, X):
 g=[[] for _ in range(n)];r=[[] for _ in range(n)]
 for a,b in edges:g[a].append(b);r[b].append(a)
 D=[[10**9]*n for _ in range(2)];D[0][0]=0;q=[(0,0,0)]
 while q:
  z,v,s=heapq.heappop(q)
  if z!=D[s][v]:continue
  if v==n-1:return z
  for ns,w,c in [(s,v,X)]+[(s,u,1) for u in (g if s==0 else r)[v]]:
   if z+c<D[ns][w]:D[ns][w]=z+c;heapq.heappush(q,(z+c,w,ns))
 return None

def slow(n,edges,X):
 states={(0,0):0}
 for it in range(10000):
  upd=False
  for (s,v),d in list(states.items()):
   for ns,w,c in [(s,v,X)]+[(s,b,1) for a,b in edges if (a==v if s==0 else b==v) for b in ([b] if s==0 else [a])]:
    if d+c<states.get((ns,w),10**9):states[ns,w]=d+c;upd=True
  if not upd:break
 return min((d for (s,v),d in states.items() if v==n-1),default=None)
