import sys
MOD=998244353
def powers(base, limit):
    result=[1]*(limit+1)
    for i in range(1,limit+1):
        result[i]=result[i-1]*base%MOD
    return result

def solve(data):
    t=list(map(int,data.split()))
    n=t[0]
    A=t[1:]
    primes=set()
    for value in A:
        x=value
        p=2
        while p*p<=x:
            if x%p==0:
                primes.add(p)
                while x%p==0:
                    x//=p
            p+=1
        if x>1:
            primes.add(x)
    answer=1
    for p in primes:
        exponents=[]
        reach=0
        for value in A:
            x=value
            e=0
            while x%p==0:
                e+=1
                x//=p
            exponents.append(e)
            reach+=e
        active=[i for i,e in enumerate(exponents) if e]
        if not active:
            continue
        first=active[0]
        hit=[0]*(reach+1)
        no_hit=[0]*(reach+1)
        hit[0]=1
        initial=powers(pow(p,first+1,MOD),reach)
        for h in range(1,reach+1):
            no_hit[h]=initial[h]
        for k,i in enumerate(active):
            d=exponents[i]
            count=active[k+1]-i if k+1<len(active) else n-1-i
            factor=powers(pow(p,count,MOD),reach)
            new_hit=[0]*(reach+1)
            new_no_hit=[0]*(reach+1)
            for h in range(reach+1):
                value=hit[h]
                if value:
                    x=h+d
                    if x<=reach:
                        new_hit[x]=(new_hit[x]+value*factor[x])%MOD
                    x=h-d
                    if x>=0:
                        new_hit[x]=(new_hit[x]+value*factor[x])%MOD
                value=no_hit[h]
                if value:
                    x=h+d
                    if x<=reach:
                        new_no_hit[x]=(new_no_hit[x]+value*factor[x])%MOD
                    x=h-d
                    if x>=0:
                        if x==0:
                            new_hit[0]=(new_hit[0]+value)%MOD
                        else:
                            new_no_hit[x]=(new_no_hit[x]+value*factor[x])%MOD
            hit,no_hit=new_hit,new_no_hit
        answer=answer*(sum(hit)%MOD)%MOD
    return str(answer)

sys.stdout.write(solve(sys.stdin.buffer.read()))

