import sys

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    a = data[1:]
    mx = max(a)

    # phi[d] lets us use gcd(x,y) = sum_{d|x,d|y} phi[d].
    phi = list(range(mx + 1))
    for p in range(2, mx + 1):
        if phi[p] == p:
            for k in range(p, mx + 1, p):
                phi[k] -= phi[k] // p

    # Precompute divisors only for values that occur in the sequence.
    present = bytearray(mx + 1)
    for x in a:
        present[x] = 1
    divisors = [[] for _ in range(mx + 1)]
    for d in range(1, mx + 1):
        for x in range(d, mx + 1, d):
            if present[x]:
                divisors[x].append(d)

    # sums[d] = sum of 2^(i-1) over processed positions i with d | A_i.
    sums = [0] * (mx + 1)
    answer = 0
    weight = 1
    out = []
    for x in a:
        s = 0
        ds = divisors[x]
        for d in ds:
            s += phi[d] * sums[d]
        s %= MOD
        # The new adjacent pair ending at this position contributes s;
        # all previous contributions double due to the new optional element.
        answer = (2 * answer + s) % MOD
        out.append(str(answer))
        for d in ds:
            sums[d] += weight
        weight = (weight * 2) % MOD

    sys.stdout.write('\n'.join(out))

if __name__ == '__main__':
    main()

