    if not data: return
    it = iter(data)
    n, q = next(it), next(it)
    parent = list(range(n)); size = [1] * n
    left = list(range(n)); right = list(range(n))
    color = list(range(1, n + 1))
    cnt = [0] + [1] * n
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def merge(a, b):
        a = find(a); b = find(b)
        if a == b: return a
        if size[a] < size[b]: a, b = b, a
        parent[b] = a
        size[a] += size[b]
        left[a] = min(left[a], left[b]); right[a] = max(right[a], right[b])
        return a
