from typing import List
import heapq
class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        by_right = [[] for _ in range(n + 1)]
        for i, (a, b) in enumerate(conflictingPairs):
            x, y = (a, b) if a < b else (b, a)
            by_right[y].append((x, i))
        heap = []
        gains = [0] * len(conflictingPairs)
        base = 0
        for r in range(1, n + 1):
            for x, i in by_right[r]:
                heapq.heappush(heap, (-x, i))
            if not heap:
                base += r
                continue
            topx = -heap[0][0]
            base += r - topx
            # Get the largest competing x; tied maximum means no unique removable constraint.
            if len(heap) == 1:
                second = 0
                idx = heap[0][1]
            else:
                first = heapq.heappop(heap)
                second = -heap[0][0]
                heapq.heappush(heap, first)
                idx = heap[0][1]
            if topx > second:
                gains[idx] += topx - second
        return base + max(gains, default=0)

