from collections import deque

def solve():
 d=list(map(int,sys.stdin.buffer.read().split())); it=iter(d)
 N=next(it); M=next(it); Q=next(it)
 people=[(next(it),next(it)) for _ in range(M)]
 queries=[(next(it),next(it)) for _ in range(Q)]
 out=[]
 for l,r in queries:
  p=list(range(N+1))
  def find(x):
   while p[x]!=x:
    p[x]=p[p[x]]; x=p[x]
   return x
  for i in range(l-1,r):
   s,t=people[i]; a=find(s); b=find(t)
   if a!=b:p[a]=b
  adj=[[] for _ in range(N+1)]; deg=[0]*(N+1); ok=True
  for i in range(l-1,r):
   s,t=people[i]; a=find(s)
   lo=min(s,t)+1; hi=max(s,t)
   for x in range(lo,hi):
    b=find(x)
    if a==b:
     ok=False; break
    u,v=(a,b) if s<t else (b,a)
    adj[u].append(v); deg[v]+=1
   if not ok:break
  if ok:
   q=deque(x for x in range(1,N+1) if find(x)==x and deg[x]==0); seen=0
   total=sum(1 for x in range(1,N+1) if find(x)==x)
   while q:
    u=q.popleft(); seen+=1
    for v in adj[u]:
     deg[v]-=1
     if deg[v]==0:q.append(v)
   ok=seen==total
  out.append('Yes' if ok else 'No')
 sys.stdout.write('\n'.join(out))
