class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        # NW, NE, SE, SW; consecutive directions are clockwise.
        dr = (-1, -1, 1, 1)
        dc = (-1, 1, 1, -1)

        @lru_cache(None)
        def go(r, c, d, need, can_turn):
            nr, nc = r + dr[d], c + dc[d]
            best = 1
            if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] == need:
                next_need = 2 - need
                best = 1 + go(nr, nc, d, next_need, can_turn)
                if can_turn:
                    best = max(best, 1 + go(nr, nc, (d + 1) % 4,
                                             next_need, False))
            return best

        answer = 0
        for r in range(n):
            for c in range(m):
                if grid[r][c] == 1:
                    answer = max(answer, 1)
                    for d in range(4):
                        answer = max(answer, go(r, c, d, 2, True))
        return answer

