class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        m = (n + 1) // 2
        coeff = []
        for i in range(m):
            j = n - 1 - i
            coeff.append((pow(10, i, k) + (pow(10, j, k) if j != i else 0)) % k)

        # suffix[i] is a bitset of residues achievable from the remaining positions.
        mask = (1 << k) - 1
        suffix = [0] * (m + 1)
        suffix[m] = 1  # residue zero
        for i in range(m - 1, -1, -1):
            reachable = 0
            c = coeff[i]
            for digit in range(10):
                shift = c * digit % k
                bits = suffix[i + 1]
                if shift:
                    bits = ((bits << shift) | (bits >> (k - shift))) & mask
                reachable |= bits
            suffix[i] = reachable

        chosen = []
        residue = 0
        for i, c in enumerate(coeff):
            minimum = 1 if i == 0 else 0
            for digit in range(9, minimum - 1, -1):
                needed = (-residue - digit * c) % k
                if (suffix[i + 1] >> needed) & 1:
                    chosen.append(str(digit))
                    residue = (residue + digit * c) % k
                    break

        half = ''.join(chosen)
        return half + (half[:-1][::-1] if n % 2 else half[::-1])

