from typing import List

class Solution:
    def maximizeSumOfWeights(self, edges: List[List[int]], k: int) -> int:
        n = len(edges) + 1
        g = [[] for _ in range(n)]
        for a, b, w in edges:
            g[a].append((b, w))
            g[b].append((a, w))

        parent = [-1] * n
        order = [0]
        for u in order:
            for v, w in g[u]:
                if v != parent[u]:
                    parent[v] = u
                    order.append(v)

        free = [0] * n
        used = [0] * n
        for u in reversed(order):
            base = 0
            gains = []
            for v, w in g[u]:
                if parent[v] == u:
                    base += free[v]
                    gains.append(w + used[v] - free[v])
            gains.sort(reverse=True)

            total = 0
            for i, gain in enumerate(gains):
                if i >= k or gain <= 0:
                    break
                total += gain
            free[u] = base + total

            total = 0
            for i, gain in enumerate(gains):
                if i >= k - 1 or gain <= 0:
                    break
                total += gain
            used[u] = base + total

        return free[0]

