        for u in order:
            for v, w in g[u]:
                if v != parent[u]:
                    parent[v] = u
                    order.append(v)

        free = [0] * n
        used = [0] * n
        for u in reversed(order):
            base = 0
            gains = []
            for v, w in g[u]:
                if parent[v] == u:
                    base += free[v]
                    gains.append(w + used[v] - free[v])
            gains.sort(reverse=True)

            total = 0
            for i, gain in enumerate(gains):
                if i >= k or gain <= 0:
                    break
                total += gain
            free[u] = base + total

            total = 0
            for i, gain in enumerate(gains):
                if i >= k - 1 or gain <= 0:
                    break
                total += gain
            used[u] = base + total

