import random
for h in range(1,5):
 for w in range(1,5):
  for z in range(100):
   f=[[random.randint(1,9) for _ in range(w)] for __ in range(h)]
   for s in range(h*w):
    best=[0]*(h*w); best[s]=f[s]; used=[False]*(h*w)
    for _ in range(h*w):
     u=max((i for i in range(h*w) if not used[i]),key=lambda i:best[i]); used[u]=True
     r,c=divmod(u,w)
     for rr,cc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
      if 0<=rr<h and 0<=cc<w:
       v=rr*w+cc; best[v]=max(best[v],min(best[u],f[rr][cc]))
    for t in range(h*w):
     # threshold connectedness check
     seen={s}; stack=[s]
     while stack:
      u=stack.pop(); r,c=divmod(u,w)
      for rr,cc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
       v=rr*w+cc
       if 0<=rr<h and 0<=cc<w and v not in seen and f[rr][cc]>=best[t]: seen.add(v);stack.append(v)
     if (t in seen)!=(best[t]>=1): print('bad');raise SystemExit
